    "prompt": "Generate one distinct fictional adult Japanese beautiful woman, age 27. IDENTITY, highest priority: a medium-length oval face, balanced midface and lower face, smoothly tapered jaw and softly contoured chin. Eyes: long slender almond eyes; level eye corners; monolids with no visible upper-lid fold; large expressive eye apertures; balanced eye spacing; naturally full lower lids. Brows: medium-width eyebrows; distinct arched brow contours; slightly rising eyebrows; moderate brow-to-eye distance. No thick or bushy eyebrows; brows must remain fine to medium in width. Nose: a moderately defined nasal bridge; a slender natural nose width; a refined tapered nose tip. Mouth: a slightly narrow mouth; naturally thin lips; upper and lower lips close in thickness; a shallow Cupid bow. Keep these anatomical contrasts clear and create an unrelated identity; do not average them into a generic idol face. High attractiveness through harmonious individual features and polished natural grooming. Naturally supported smooth cheeks, no sunken cheeks, no buccal hollows, no dark concave cheekbone shadows. Round faces remain petite with modest cheek fullness, no heavy puffiness or double chin. Normal slim neck. Mouth small to average, lips thin to moderate, no plumped lips. Hair: straight black shoulder-length hair with a soft, loosely separated fringe falling naturally over the eyebrows; wispy tips reach just below the eyebrows but stay out of the eyes; side hair tucked behind the ears, no rounded bowl silhouette and no blunt straight fringe. Dark brown irises, natural black hair, realistic skin texture. Minimal natural makeup, no winged eyeliner, no dramatic false lashes, no contour makeup, no facial hair, jewelry or glasses. Realistic editorial beauty photo, front-facing head level, eyes at camera, neutral expression, closed lips. Plain light-gray crew-neck shirt, neutral light-gray studio background, soft even frontal lighting. Vertical 3:4 portrait, full head, shoulders and mid-chest visible. Face from hairline to chin about 38 percent of image height, face center at 50 percent width and 38 percent height. Eyes and full cheek/jaw outline unobstructed. For downward fringe, allow partial eyebrow coverage with natural separated strands. No tight crop, no text, no watermark.",
